//! Append-only, workspace-scoped activity records for real local changes.
//! Event summaries are generated by trusted services; no raw user content,
//! credentials, task descriptions or arbitrary metadata enter the event store.

use rusqlite::{params, Connection, Transaction};
use uuid::Uuid;

const PROJECT_ACTIVITY_LIMIT: i64 = 10;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProjectActivity {
    pub id: String,
    pub entity_type: String,
    pub action: String,
    pub summary: String,
    pub occurred_at: String,
}

/// Reads recent, trusted activity for a project and its currently linked tasks.
pub fn list_project_activity(
    connection: &Connection,
    workspace_id: &str,
    project_id: &str,
) -> Result<Vec<ProjectActivity>, String> {
    let workspace_id = workspace_id.trim();
    let project_id = project_id.trim();
    if workspace_id.is_empty() || project_id.is_empty() {
        return Err("VALIDATION_FAILED: project and workspace IDs are required".to_string());
    }
    let mut statement = connection
        .prepare(
            "SELECT id, entity_type, action, summary, occurred_at
             FROM activity_events
             WHERE workspace_id = ?1
               AND (project_id = ?2 OR task_id IN (
                    SELECT id FROM tasks WHERE workspace_id = ?1 AND project_id = ?2
               ))
             ORDER BY occurred_at DESC, id DESC
             LIMIT ?3",
        )
        .map_err(|_| "IO_ERROR: could not prepare project activity list".to_string())?;
    let rows = statement
        .query_map(
            params![workspace_id, project_id, PROJECT_ACTIVITY_LIMIT],
            |row| {
                Ok(ProjectActivity {
                    id: row.get(0)?,
                    entity_type: row.get(1)?,
                    action: row.get(2)?,
                    summary: row.get(3)?,
                    occurred_at: row.get(4)?,
                })
            },
        )
        .map_err(|_| "IO_ERROR: could not list project activity".to_string())?;
    rows.collect::<rusqlite::Result<Vec<_>>>()
        .map_err(|_| "IO_ERROR: could not read project activity".to_string())
}

#[derive(Debug, Clone, Copy)]
pub enum ActivityEntityKind {
    Project,
    Task,
}

#[derive(Debug, Clone, Copy)]
pub enum ActivityAction {
    Created,
    Updated,
    Archived,
    Restored,
}

impl ActivityAction {
    fn values(self, kind: ActivityEntityKind) -> (&'static str, &'static str, &'static str) {
        match (kind, self) {
            (ActivityEntityKind::Project, Self::Created) => {
                ("project", "created", "Project created")
            }
            (ActivityEntityKind::Task, Self::Created) => ("task", "created", "Task created"),
            (ActivityEntityKind::Project, Self::Updated) => {
                ("project", "updated", "Project updated")
            }
            (ActivityEntityKind::Task, Self::Updated) => ("task", "updated", "Task updated"),
            (ActivityEntityKind::Project, Self::Archived) => {
                ("project", "archived", "Project archived")
            }
            (ActivityEntityKind::Task, Self::Archived) => ("task", "archived", "Task archived"),
            (ActivityEntityKind::Task, Self::Restored) => ("task", "restored", "Task restored"),
            (ActivityEntityKind::Project, Self::Restored) => {
                ("project", "restored", "Project restored")
            }
        }
    }
}

/// Called inside the entity's existing transaction: no partial entity/event pair.
pub fn record_creation(
    transaction: &Transaction<'_>,
    workspace_id: &str,
    kind: ActivityEntityKind,
    entity_id: &str,
) -> Result<(), String> {
    record_change(
        transaction,
        workspace_id,
        kind,
        entity_id,
        ActivityAction::Created,
    )
}

pub fn record_change(
    transaction: &Transaction<'_>,
    workspace_id: &str,
    kind: ActivityEntityKind,
    entity_id: &str,
    action: ActivityAction,
) -> Result<(), String> {
    let (entity_type, action_code, summary) = action.values(kind);
    let project_id = (entity_type == "project").then_some(entity_id);
    let task_id = (entity_type == "task").then_some(entity_id);
    transaction
        .execute(
            "INSERT INTO activity_events
                (id, workspace_id, entity_type, entity_id,
                 project_id, task_id, action, summary)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
            params![
                Uuid::new_v4().to_string(),
                workspace_id,
                entity_type,
                entity_id,
                project_id,
                task_id,
                action_code,
                summary
            ],
        )
        .map_err(|_| "IO_ERROR: could not record activity event".to_string())?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{projects, tasks};
    use rusqlite::Connection;

    const PERSONAL: &str = "00000000-0000-4000-8000-000000000001";

    #[derive(Debug)]
    struct RecordedActivity {
        workspace_id: String,
        entity_type: String,
        entity_id: String,
        action: String,
        summary: String,
        occurred_at: String,
        sensitivity: String,
        actor_type: String,
    }

    fn fixture() -> Connection {
        let mut connection = Connection::open_in_memory().expect("disposable database");
        connection
            .execute_batch("PRAGMA foreign_keys = ON;")
            .expect("enable foreign keys");
        crate::run_migrations(&mut connection).expect("schema");
        connection
    }

    #[test]
    fn project_and_task_creates_persist_real_scoped_activity_without_user_text() {
        let mut connection = fixture();
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Sensitive project name".to_string(),
                project_key: None,
                description: Some("secret-description-never-audit".to_string()),
                goal: None,
                status: None,
            },
        )
        .expect("project with event");
        let task = tasks::create_task(
            &mut connection,
            tasks::CreateTask {
                workspace_id: PERSONAL.to_string(),
                project_id: Some(project.id.clone()),
                title: "Sensitive task title".to_string(),
                description: Some("secret-task-description".to_string()),
                due_at: None,
                status: None,
                priority: None,
            },
        )
        .expect("task with event");

        let mut statement = connection
            .prepare(
                "SELECT workspace_id, entity_type, entity_id, action, summary,
                        occurred_at, sensitivity, actor_type
                 FROM activity_events ORDER BY rowid",
            )
            .expect("activity query");
        let events: Vec<RecordedActivity> = statement
            .query_map([], |row| {
                Ok(RecordedActivity {
                    workspace_id: row.get(0)?,
                    entity_type: row.get(1)?,
                    entity_id: row.get(2)?,
                    action: row.get(3)?,
                    summary: row.get(4)?,
                    occurred_at: row.get(5)?,
                    sensitivity: row.get(6)?,
                    actor_type: row.get(7)?,
                })
            })
            .expect("rows")
            .map(|row| row.expect("row"))
            .collect();
        assert_eq!(events.len(), 2);
        assert_eq!(events[0].workspace_id, PERSONAL);
        assert_eq!(events[0].entity_type, "project");
        assert_eq!(events[0].entity_id, project.id);
        assert_eq!(events[1].entity_type, "task");
        assert_eq!(events[1].entity_id, task.id);
        assert_eq!(events[0].action, "created");
        assert_eq!(events[1].action, "created");
        assert_eq!(events[0].summary, "Project created");
        assert_eq!(events[1].summary, "Task created");
        for event in events {
            assert!(
                event.occurred_at.ends_with('Z'),
                "activity timestamp uses UTC"
            );
            assert!(!event.occurred_at.is_empty());
            assert_eq!(event.sensitivity, "normal");
            assert_eq!(event.actor_type, "local");
            assert!(!event.summary.contains("secret"));
            assert!(!event.summary.contains("Sensitive"));
        }
    }

    #[test]
    fn project_activity_reads_only_project_and_linked_task_events_without_user_text() {
        let mut connection = fixture();
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Project activity fixture".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("project");
        let other_project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Other project".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("other project");
        let task = tasks::create_task(
            &mut connection,
            tasks::CreateTask {
                workspace_id: PERSONAL.to_string(),
                project_id: Some(project.id.clone()),
                title: "Private task title".to_string(),
                description: Some("Private task description".to_string()),
                due_at: None,
                status: None,
                priority: None,
            },
        )
        .expect("linked task");
        tasks::create_task(
            &mut connection,
            tasks::CreateTask {
                workspace_id: PERSONAL.to_string(),
                project_id: Some(other_project.id),
                title: "Unrelated task title".to_string(),
                description: None,
                due_at: None,
                status: None,
                priority: None,
            },
        )
        .expect("unrelated task");
        tasks::update_task(
            &mut connection,
            tasks::UpdateTask {
                workspace_id: PERSONAL.to_string(),
                id: task.id,
                project_id: Some(project.id.clone()),
                title: "Private task title".to_string(),
                description: Some("Private task description".to_string()),
                due_at: None,
                status: "in_progress".to_string(),
                priority: "p2".to_string(),
            },
        )
        .expect("task update");

        let events = list_project_activity(&connection, PERSONAL, &project.id)
            .expect("read project activity");
        assert_eq!(events.len(), 3);
        assert!(events
            .iter()
            .any(|event| { event.entity_type == "project" && event.summary == "Project created" }));
        assert!(events
            .iter()
            .any(|event| event.entity_type == "task" && event.summary == "Task created"));
        assert!(events
            .iter()
            .any(|event| event.entity_type == "task" && event.summary == "Task updated"));
        assert!(events.iter().all(|event| {
            event.occurred_at.ends_with('Z')
                && !event.summary.contains("Private")
                && !event.summary.contains("Unrelated")
        }));
    }

    #[test]
    fn project_activity_is_bounded_and_workspace_scoped() {
        let mut connection = fixture();
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Bounded project".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("project");
        for index in 0..12 {
            tasks::create_task(
                &mut connection,
                tasks::CreateTask {
                    workspace_id: PERSONAL.to_string(),
                    project_id: Some(project.id.clone()),
                    title: format!("Task {index}"),
                    description: None,
                    due_at: None,
                    status: None,
                    priority: None,
                },
            )
            .expect("task");
        }
        assert_eq!(
            list_project_activity(&connection, PERSONAL, &project.id)
                .expect("bounded project activity")
                .len(),
            PROJECT_ACTIVITY_LIMIT as usize
        );
        assert!(
            list_project_activity(&connection, "other-workspace", &project.id)
                .expect("other workspace has no matching project activity")
                .is_empty()
        );
    }

    #[test]
    fn activity_schema_rejects_missing_or_cross_workspace_entity_references() {
        let mut connection = fixture();
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Valid".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("fixture project");
        connection
            .execute(
                "INSERT INTO workspaces (id, name) VALUES ('other', 'Other')",
                [],
            )
            .expect("other workspace");
        assert!(connection
            .execute(
                "INSERT INTO activity_events
                    (id, workspace_id, entity_type, entity_id, project_id, action, summary)
                 VALUES ('wrong-workspace', 'other', 'project', ?1, ?1, 'created', 'Safe')",
                params![project.id],
            )
            .is_err());
        assert!(connection
            .execute(
                "INSERT INTO activity_events
                    (id, workspace_id, entity_type, entity_id, project_id, action, summary)
                 VALUES ('missing-project', ?1, 'project', 'missing', 'missing', 'created', 'Safe')",
                params![PERSONAL],
            )
            .is_err());
        assert!(connection
            .execute(
                "INSERT INTO activity_events
                    (id, workspace_id, entity_type, entity_id, project_id, action, summary)
                 VALUES ('mismatch', ?1, 'project', 'wrong-id', ?2, 'created', 'Safe')",
                params![PERSONAL, project.id],
            )
            .is_err());
        let count: i64 = connection
            .query_row("SELECT COUNT(*) FROM activity_events", [], |row| row.get(0))
            .expect("event count");
        assert_eq!(count, 1, "invalid attempts cannot append activity");
    }

    #[test]
    fn failed_event_write_rolls_back_project_and_task_creation() {
        let mut connection = fixture();
        connection
            .execute_batch(
                "CREATE TRIGGER reject_activity
                 BEFORE INSERT ON activity_events
                 BEGIN
                     SELECT RAISE(ABORT, 'synthetic activity failure');
                 END;",
            )
            .expect("failure injection");
        let project_error = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Will rollback".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect_err("event failure must abort entity transaction");
        assert!(project_error.starts_with("IO_ERROR:"));
        let count: i64 = connection
            .query_row("SELECT COUNT(*) FROM projects", [], |row| row.get(0))
            .unwrap();
        assert_eq!(count, 0);
        connection
            .execute_batch("DROP TRIGGER reject_activity")
            .expect("remove injection");
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Good".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("create allowed project");
        connection
            .execute_batch(
                "CREATE TRIGGER reject_activity
                 BEFORE INSERT ON activity_events
                 BEGIN
                     SELECT RAISE(ABORT, 'synthetic activity failure');
                 END;",
            )
            .expect("restore injection");
        let task_error = tasks::create_task(
            &mut connection,
            tasks::CreateTask {
                workspace_id: PERSONAL.to_string(),
                project_id: Some(project.id),
                title: "Rollback task".to_string(),
                description: None,
                due_at: None,
                status: None,
                priority: None,
            },
        )
        .expect_err("task and event must commit together");
        assert!(task_error.starts_with("IO_ERROR:"));
        let task_count: i64 = connection
            .query_row("SELECT COUNT(*) FROM tasks", [], |row| row.get(0))
            .unwrap();
        assert_eq!(task_count, 0);
    }
}
